/**
 * Constants from CPython's `string` module.
 *
 * Only the members that `boltons.strutils` builds its separator pattern from are
 * reproduced here. The exact character ORDER matters: the pattern that drives
 * `slugify()` is assembled by string concatenation and then parsed as a regular
 * expression character class, and character-class semantics are order sensitive
 * (adjacent characters can form ranges, a backslash escapes the next character).
 * See ./re_charclass.mjs for why that is load bearing.
 */

/** `string.punctuation` — the 32 printable ASCII characters that are not alphanumeric. */
export const punctuation = '!"#$%&\'()*+,-./:;<=>?@[\\]^_`{|}~';

/** `string.whitespace` — space, tab, linefeed, carriage return, vertical tab, formfeed. */
export const whitespace = ' \t\n\r\v\f';

/** `string.ascii_lowercase` */
export const asciiLowercase = 'abcdefghijklmnopqrstuvwxyz';

/** `string.ascii_uppercase` */
export const asciiUppercase = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';

/** `string.digits` */
export const digits = '0123456789';

