/**
 * A faithful port of the character-class parser inside CPython's `re` module
 * (`sre_parse`), restricted to the constructs that can appear in a class body.
 *
 * WHY THIS EXISTS
 * ---------------
 * `boltons.strutils` derives its word separator pattern by concatenating
 * `string.punctuation` and `string.whitespace` straight into a character class:
 *
 *     '[' + string.punctuation + string.whitespace + ']+'
 *
 * The punctuation string is NOT escaped first, so the resulting class body is
 * re-parsed as regex source and two of its characters stop being plain literals:
 *
 *   - `,-.`  the hyphen between `,` and `.` forms a RANGE (U+002C..U+002E).
 *            Harmless here: the range covers exactly `,` `-` `.`, which were the
 *            literals anyway.
 *   - `[\]`  the backslash ESCAPES the following `]`. That keeps the class open
 *            (otherwise it would have terminated early) but it also means the
 *            backslash itself is consumed as an escape marker and never joins the
 *            set. A literal backslash is therefore NOT a separator, even though it
 *            is a member of `string.punctuation`.
 *
 * Deriving the set through a real parser instead of hardcoding 37 code points keeps
 * that quirk auditable: the surprising exclusion of `\` falls out of the same rules
 * CPython applies, rather than being an unexplained hole in a literal table.
 */

/** Single-character escapes recognised inside a class body (`sre_parse.ESCAPES`). */
const ESCAPES = new Map([
  ['a', 0x07], // BEL
  ['b', 0x08], // BS — inside a class `\b` is backspace, not a word boundary
  ['f', 0x0c],
  ['n', 0x0a],
  ['r', 0x0d],
  ['t', 0x09],
  ['v', 0x0b],
  ['\\', 0x5c],
]);

/** Escapes that denote a character CATEGORY rather than a single code point. */
const CATEGORIES = new Set(['d', 'D', 's', 'S', 'w', 'W']);

const OCT_DIGITS = '01234567';
const HEX_DIGITS = '0123456789abcdefABCDEF';

const isAsciiAlpha = (ch) => /^[A-Za-z]$/.test(ch);

/**
 * Reads one class member starting at `src[i]`, which is known to be a backslash.
 * Returns `{ code, next }` where `code` is the code point of the escaped literal.
 * Mirrors `sre_parse._class_escape`.
 */
function readClassEscape(src, i) {
  const ch = src[i + 1];
  if (ch === undefined) {
    throw new SyntaxError('bad escape (end of pattern)');
  }
  if (ESCAPES.has(ch)) {
    return { code: ESCAPES.get(ch), next: i + 2 };
  }
  if (CATEGORIES.has(ch)) {
    // `\d`, `\s`, ... are sets, not single code points. `slugify()`'s pattern never
    // uses them, and supporting them would change the return type of this parser,
    // so refuse loudly instead of guessing.
    throw new SyntaxError(`unsupported category escape \\${ch} in character class`);
  }
  if (ch === 'x' || ch === 'u' || ch === 'U') {
    const width = ch === 'x' ? 2 : ch === 'u' ? 4 : 8;
    const digits = src.slice(i + 2, i + 2 + width);
    if (digits.length !== width || [...digits].some((d) => !HEX_DIGITS.includes(d))) {
      throw new SyntaxError(`incomplete escape \\${ch}${digits}`);
    }
    return { code: parseInt(digits, 16), next: i + 2 + width };
  }
  if (OCT_DIGITS.includes(ch)) {
    let digits = '';
    while (digits.length < 3 && OCT_DIGITS.includes(src[i + 1 + digits.length] ?? '')) {
      digits += src[i + 1 + digits.length];
    }
    return { code: parseInt(digits, 8), next: i + 1 + digits.length };
  }
  if (isAsciiAlpha(ch) || /[0-9]/.test(ch)) {
    // CPython reserves unknown alphanumeric escapes for future syntax.
    throw new SyntaxError(`bad escape \\${ch}`);
  }
  return { code: ch.codePointAt(0), next: i + 2 };
}

/**
 * Parses the body of a regex character class (the text between `[` and its
 * matching `]`) and returns the set of code points it matches.
 *
 * @param {string} body Class body WITHOUT the enclosing brackets.
 * @returns {{ negated: boolean, codePoints: Set<number> }}
 */
export function parseCharClassBody(body) {
  const src = [...body]; // iterate by code point, as CPython does
  const codePoints = new Set();
  let i = 0;
  let negated = false;

  if (src[i] === '^') {
    negated = true;
    i += 1;
  }

  // A `]` in the first position is a literal; anywhere else it would have closed
  // the class before this function was ever called.
  let first = true;

  while (i < src.length) {
    if (src[i] === ']' && !first) {
      throw new SyntaxError('unescaped "]" inside character class body');
    }
    first = false;

    let lo;
    if (src[i] === '\\') {
      const escaped = readClassEscape(src, i);
      lo = escaped.code;
      i = escaped.next;
    } else {
      lo = src[i].codePointAt(0);
      i += 1;
    }

    // `X-Y` is a range, but a trailing `-` (nothing left to consume) is a literal.
    if (src[i] === '-' && i + 1 < src.length) {
      i += 1;
      let hi;
      if (src[i] === '\\') {
        const escaped = readClassEscape(src, i);
        hi = escaped.code;
        i = escaped.next;
      } else {
        hi = src[i].codePointAt(0);
        i += 1;
      }
      if (hi < lo) {
        throw new SyntaxError(
          `bad character range ${String.fromCodePoint(lo)}-${String.fromCodePoint(hi)}`,
        );
      }
      for (let cp = lo; cp <= hi; cp += 1) codePoints.add(cp);
      continue;
    }

    codePoints.add(lo);
    if (src[i] === '-' && i + 1 === src.length) {
      codePoints.add(0x2d);
      i += 1;
    }
  }

  return { negated, codePoints };
}

