/**
 * Port of the `slugify` / `split_punct_ws` pair from `boltons.strutils`.
 *
 * Reproduced from observed behaviour only (the Python package is treated as a black
 * box). Every rule below was confirmed byte-for-byte against the reference binary.
 */

import { punctuation, whitespace } from '../py/string_constants.mjs';
import { parseCharClassBody } from '../py/re_charclass.mjs';
import { lower as pyLower } from '../py/str_case.mjs';

/**
 * The class body `boltons` splices together for its separator pattern,
 * `'[' + string.punctuation + string.whitespace + ']+'`.
 */
const PUNCT_WS_CLASS_BODY = punctuation + whitespace;

/**
 * Code points that separate words.
 *
 * Parsing the class body rather than listing the members is deliberate — it is what
 * makes the absence of `\` (U+005C) explicit and self-explaining. Resulting set (37
 * code points):
 *
 *   TAB LF VT FF CR SPACE  ! " # $ % & ' ( ) * + , - . /  : ; < = > ? @  [ ] ^ _ `  { | } ~
 *
 * Note what is NOT here: `\` (swallowed as an escape while parsing the class), and
 * every non-ASCII character. Unicode spaces and punctuation — U+00A0 NO-BREAK SPACE,
 * U+2003 EM SPACE, U+3000 IDEOGRAPHIC SPACE, U+2014 EM DASH, U+00B7 MIDDLE DOT,
 * U+FF01 FULLWIDTH EXCLAMATION MARK, … — are ordinary word characters here, because
 * `string.punctuation` and `string.whitespace` are pure ASCII.
 */
const SEPARATORS = (() => {
  const { negated, codePoints } = parseCharClassBody(PUNCT_WS_CLASS_BODY);
  if (negated) throw new Error('separator class must not be negated');
  return codePoints;
})();

/** True when `codeUnit` is one of the 37 separator code points. */
function isSeparator(codeUnit) {
  return SEPARATORS.has(codeUnit);
}

/**
 * Splits `text` on runs of punctuation and whitespace, dropping empty pieces.
 *
 * Equivalent to `[w for w in re.split('[<punct><ws>]+', text) if w]`: a run of any
 * length collapses to a single split point, and leading/trailing runs yield empty
 * pieces that are filtered out.
 *
 * Scanning UTF-16 code units is safe even though CPython scans code points: every
 * separator is below U+0080, so no surrogate code unit can ever compare equal to one
 * and no astral character can be split down the middle.
 *
 * @param {string} text
 * @returns {string[]}
 */
export function splitPunctWs(text) {
  const words = [];
  let start = 0;
  for (let i = 0; i < text.length; i += 1) {
    if (!isSeparator(text.charCodeAt(i))) continue;
    if (i > start) words.push(text.slice(start, i));
    start = i + 1;
  }
  if (text.length > start) words.push(text.slice(start));
  return words;
}

/**
 * Turns `text` into a slug: words joined by `delim`, lowercased.
 *
 * Two behaviours are easy to get wrong and both are load bearing:
 *
 *  1. DEGENERATE INPUT. Input made up entirely of separators has no words at all,
 *     yet it does not produce the empty string — it produces exactly one `delim`.
 *     `slugify('!')`, `slugify('!!!')`, `slugify('   ')` and `slugify('\t')` all
 *     return `'_'`, never `''` and never `'___'`. Only a genuinely empty input
 *     returns the empty string.
 *
 *  2. LOWERCASING ORDER. Case folding is applied to the ALREADY-JOINED string, not
 *     to each word. That is observable: Greek capital sigma lowercases to final
 *     sigma `ς` when it ends a word, and whether a sigma counts as word-final
 *     depends on the `_` that the join inserted after it. `slugify('ΟΔΟΣ ΟΔΟΣ')`
 *     is `'οδος_οδος'` — both sigmas final — which per-word lowercasing would also
 *     get right, but the general rule only holds if the join happens first.
 *
 * @param {string} text
 * @param {{ delim?: string, lower?: boolean }} [options]
 * @returns {string}
 */
export function slugify(text, options = {}) {
  const { delim = '_', lower = true } = options;

  const words = splitPunctWs(text);
  // See note 1: an all-separator input collapses to a single delimiter.
  const joined = words.length === 0 ? (text.length === 0 ? '' : delim) : words.join(delim);

  // See note 2: lowercase the joined string as a whole.
  return lower ? pyLower(joined) : joined;
}

