/**
 * Exception types used by the argument parser, mirroring CPython's `argparse`.
 */

/**
 * Raised while an individual argument is being processed. Rendered as
 * `argument <name>: <message>` — e.g. `argument --a: expected one argument`.
 */
export class ArgumentError extends Error {
  /**
   * @param {?string} argumentName Primary option string, or null for a bare message.
   * @param {string} message
   */
  constructor(argumentName, message) {
    super(argumentName === null ? message : `argument ${argumentName}: ${message}`);
    this.name = 'ArgumentError';
    this.argumentName = argumentName;
    this.rawMessage = message;
  }
}

/**
 * Stands in for Python's `SystemExit`. The parser never touches the process itself;
 * it hands the caller the exit status plus whatever should be written to each stream,
 * which keeps parsing pure and testable.
 */
export class ParserExit extends Error {
  /**
   * @param {number} code
   * @param {{ stdout?: string, stderr?: string }} [streams]
   */
  constructor(code, streams = {}) {
    super(`parser exit ${code}`);
    this.name = 'ParserExit';
    this.code = code;
    this.stdout = streams.stdout ?? '';
    this.stderr = streams.stderr ?? '';
  }
}

