      const parts = [...optParts, ...posParts];
      lines = parts.length > 1 ? [...getLines(optParts, indent), ...getLines(posParts, indent)] : [prog];
      if (parts.length > 1) lines = [prog, ...lines];
    }
    usage = lines.join('\n');
  }

