/**
 * A port of the slice of `argparse.ArgumentParser` that this CLI exercises.
 *
 * The goal is behavioural equivalence with CPython, not a general-purpose parser: the
 * awkward parts of `argparse` that are reproduced here are exactly the ones that are
 * observable from the command line.
 *
 *   - Long options may be abbreviated to any unambiguous prefix, so `--hel` and `--h`
 *     both reach `--help`.
 *   - `--opt=value` is accepted as well as `--opt value`.
 *   - A token beginning with `-` is normally treated as an option, so `--a -x` fails
 *     with "expected one argument" rather than storing `-x`. The exception is tokens
 *     that look like negative numbers (`-5`, `-1.5`) and tokens containing a space —
 *     those are values, because no registered option could be confused for them.
 *   - `--` marks everything after it as non-option, but it is not itself discarded
 *     when there are no positionals to absorb it, so `--a x --` reports
 *     "unrecognized arguments: --".
 *   - `-h` fires the instant it is scanned, so it wins over any later error.
 *   - Missing required options are reported BEFORE leftover unrecognized arguments,
 *     because the required check happens inside `parse_known_args` while the
 *     unrecognized check happens in its caller.
 */

import { ArgumentError, ParserExit } from './errors.mjs';
import { HelpAction, StoreAction } from './actions.mjs';
import { formatHelp, formatUsage, getFormatterWidth } from './formatter.mjs';

/**
 * `argparse._negative_number_matcher`. A token matching this is read as a value
 * rather than an option, provided no registered option string looks like a negative
 * number itself.
 */
const NEGATIVE_NUMBER_RE = /^-\d+$|^-\d*\.\d+$/;

export class ArgumentParser {
  /**
   * @param {{ prog?: string, prefixChars?: string, addHelp?: boolean,
   *           width?: number }} [options]
   */
  constructor(options = {}) {
    const { prog, prefixChars = '-', addHelp = true, width } = options;
    this.prog = prog ?? 'prog';
    this.prefixChars = prefixChars;
    this.width = width ?? getFormatterWidth();

    /** @type {object[]} every action, in declaration order */
    this.actions = [];
    /** @type {Map<string, object>} option string -> action */
    this.optionStringActions = new Map();
    /** Default `argparse` groups; the positional group stays empty here. */
    this.groups = [
      { title: 'positional arguments', actions: [] },
      { title: 'options', actions: [] },
    ];

    if (addHelp) {
      this.registerAction(
        new HelpAction({
          optionStrings: [`${this.prefixChars[0]}h`, `${this.prefixChars[0].repeat(2)}help`],
          help: 'show this help message and exit',
        }),
      );
    }
  }

  /** Registers an action and indexes each of its option strings. */
  registerAction(action) {
    this.actions.push(action);
    const group = action.optionStrings.length > 0 ? this.groups[1] : this.groups[0];
    group.actions.push(action);
    for (const optionString of action.optionStrings) {
      this.optionStringActions.set(optionString, action);
    }
    return action;
  }

  /**
   * `add_argument('--a', type=str, required=True)`.
   *
   * @param {string|string[]} names
   * @param {{ required?: boolean, type?: (v: string) => unknown, metavar?: string,
   *           help?: string, dest?: string }} [spec]
   */
  addArgument(names, spec = {}) {
    const optionStrings = Array.isArray(names) ? names : [names];
    // `dest` comes from the first long option, with prefix chars stripped and
    // internal dashes turned into underscores.
    const longest = optionStrings.find((s) => s.startsWith(this.prefixChars.repeat(2)));
    const source = longest ?? optionStrings[0];
    const dest =
      spec.dest ??
      source.replace(new RegExp(`^[${this.prefixChars}]+`), '').replace(/-/g, '_');
    return this.registerAction(new StoreAction({ ...spec, optionStrings, dest }));
  }

  /** True when any registered option string could be mistaken for a negative number. */
  get hasNegativeNumberOptionals() {
    for (const optionString of this.optionStringActions.keys()) {
      if (NEGATIVE_NUMBER_RE.test(optionString)) return true;
    }
    return false;
  }

  formatUsage() {
    return formatUsage(this.prog, this.actions, this.width);
  }

  formatHelp() {
    return formatHelp(this.prog, this.actions, this.groups, this.width);
  }

  /** `print_help()` then `sys.exit(0)` — help goes to stdout. */
  exitWithHelp() {
    throw new ParserExit(0, { stdout: this.formatHelp() });
  }

  /**
   * `ArgumentParser.error()`: usage line and message to stderr, exit status 2.
   * @param {string} message
   */
  error(message) {
    throw new ParserExit(2, {
      stderr: `${this.formatUsage()}${this.prog}: error: ${message}\n`,
    });
  }

  /**
   * `_parse_optional`: decides whether `token` is an option, and if so which one.
   *
   * @returns {?{ action: ?object, optionString: string, explicitArg: ?string }}
   *   `null` means "this is not an option"; an entry with `action: null` means
   *   "looks like an option but no such option exists".
   */
  parseOptional(token) {
    if (token.length === 0) return null;
    if (!this.prefixChars.includes(token[0])) return null;

    if (this.optionStringActions.has(token)) {
      return { action: this.optionStringActions.get(token), optionString: token, explicitArg: null };
    }
    // A lone `-` is a positional by convention (conventionally stdin).
    if (token.length === 1) return null;

    const eq = token.indexOf('=');
    if (eq !== -1) {
      const head = token.slice(0, eq);
      if (this.optionStringActions.has(head)) {
        return {
          action: this.optionStringActions.get(head),
          optionString: head,
          explicitArg: token.slice(eq + 1),
        };
      }
    }

    const candidates = this.getOptionTuples(token);
    if (candidates.length > 1) {
      const matches = candidates.map((c) => c.optionString).join(', ');
      this.error(`ambiguous option: ${token} could match ${matches}`);
    }
    if (candidates.length === 1) return candidates[0];

    // Negative numbers are values, unless an option could be confused for one.
    if (NEGATIVE_NUMBER_RE.test(token) && !this.hasNegativeNumberOptionals) return null;
    // Anything containing a space was clearly meant as a value.
    if (token.includes(' ')) return null;

    return { action: null, optionString: token, explicitArg: null };
  }

  /** `_get_option_tuples`: prefix matches for abbreviated options. */
  getOptionTuples(token) {
    const result = [];
    const isLong = this.prefixChars.includes(token[0]) && this.prefixChars.includes(token[1]);

    if (isLong) {
      const eq = token.indexOf('=');
      const prefix = eq === -1 ? token : token.slice(0, eq);
      const explicitArg = eq === -1 ? null : token.slice(eq + 1);
      for (const [optionString, action] of this.optionStringActions) {
        if (optionString.startsWith(prefix)) result.push({ action, optionString, explicitArg });
      }
      return result;
    }

    // Single-dash: `-xVALUE` may pack a value onto a one-character option.
    const shortPrefix = token.slice(0, 2);
    const shortExplicitArg = token.slice(2);
    for (const [optionString, action] of this.optionStringActions) {
      if (optionString === shortPrefix) {
        result.push({ action, optionString, explicitArg: shortExplicitArg });
      } else if (optionString.startsWith(token)) {
        result.push({ action, optionString, explicitArg: null });
      }
    }
    return result;
  }

  /**
   * `parse_known_args`: fills a namespace and returns any leftover tokens.
   * @param {string[]} argv
   */
  parseKnownArgs(argv) {
    const namespace = Object.create(null);
    for (const action of this.actions) {
      if (action instanceof StoreAction) namespace[action.dest] = null;
    }

    // Pass 1: classify every token as an Option, an Argument, or the `--` marker.
    const optionTuples = new Map();
    const pattern = [];
    for (let i = 0; i < argv.length; i += 1) {
      if (argv[i] === '--') {
        pattern.push('-');
        for (let j = i + 1; j < argv.length; j += 1) pattern.push('A');
        break;
      }
      const tuple = this.parseOptional(argv[i]);
      if (tuple === null) {
        pattern.push('A');
      } else {
        optionTuples.set(i, tuple);
        pattern.push('O');
      }
    }

    const extras = [];
    const seen = new Set();

    const takeAction = (action, values, optionString) => {
      seen.add(action);
      action.call(namespace, values, optionString, this);
    };

    /**
     * `consume_optional`: applies the option at `startIndex` and returns the index
     * just past whatever it consumed.
     */
    const consumeOptional = (startIndex) => {
      let { action, optionString, explicitArg } = optionTuples.get(startIndex);

      if (action === null) {
        extras.push(argv[startIndex]);
        return startIndex + 1;
      }

      if (explicitArg !== null) {
        if (action.argCount === 1) {
          takeAction(action, [this.convert(action, explicitArg)], optionString);
          return startIndex + 1;
        }
        // e.g. `--help=x` — the option takes nothing, so the value is an error.
        throw new ArgumentError(
          action.optionStrings[0],
          `ignored explicit argument '${explicitArg}'`,
        );
      }

      // Only tokens classified as plain Arguments may be swallowed as values;
      // an `O` or the `--` marker means the value is missing.
      const available = pattern.slice(startIndex + 1);
      let taken = 0;
      while (taken < action.argCount) {
        if (available[taken] !== 'A') {
          throw new ArgumentError(action.optionStrings[0], 'expected one argument');
        }
        taken += 1;
      }
      const values = argv
        .slice(startIndex + 1, startIndex + 1 + taken)
        .map((raw) => this.convert(action, raw));
      takeAction(action, values, optionString);
      return startIndex + 1 + taken;
    };

    // Pass 2: walk left to right. With no positionals declared, every token that is
    // not an option and not consumed as an option's value becomes an extra.
    const optionIndices = [...optionTuples.keys()].sort((a, b) => a - b);
    let index = 0;
    for (const optionIndex of optionIndices) {
      if (optionIndex < index) continue; // already consumed as a value
      if (optionIndex > index) {
        extras.push(...argv.slice(index, optionIndex));
        index = optionIndex;
      }
      index = consumeOptional(index);
    }
    extras.push(...argv.slice(index));

    const missing = this.actions
      .filter((action) => action.required && !seen.has(action))
      .map((action) => action.optionStrings[0] ?? action.dest);
    if (missing.length > 0) {
      this.error(`the following arguments are required: ${missing.join(', ')}`);
    }

    return { namespace, extras };
  }

  /** `_get_value`: runs the `type` callable. */
  convert(action, raw) {
    return action.type ? action.type(raw) : raw;
  }

  /**
   * `parse_args`: like `parseKnownArgs`, but leftover tokens are an error.
   * @param {string[]} argv
   */
  parseArgs(argv) {
    let result;
    try {
      result = this.parseKnownArgs(argv);
    } catch (err) {
      if (err instanceof ArgumentError) this.error(err.message);
      throw err;
    }
    if (result.extras.length > 0) {
      this.error(`unrecognized arguments: ${result.extras.join(' ')}`);
    }
    return result.namespace;
  }
}

