import { spawnSync } from 'node:child_process';
const BIN = '/workspace/dataset/test4_executable';
// ASCII punctuation minus backslash, plus ASCII whitespace = separators
const SEP = new Set([0x09,0x0a,0x0b,0x0c,0x0d,0x20,...Array.from({length:15},(_,i)=>0x21+i),
  ...Array.from({length:7},(_,i)=>0x3a+i),0x5b,0x5d,0x5e,0x5f,0x60,0x7b,0x7c,0x7d,0x7e]);

// candidate codepoints: everything whose toLowerCase differs, across all planes
const cands = [];
for (let cp = 0; cp <= 0x10ffff; cp++) {
  if (cp >= 0xd800 && cp <= 0xdfff) continue;
  if (SEP.has(cp)) continue;
  const ch = String.fromCodePoint(cp);
  if (ch.toLowerCase() !== ch) cands.push(cp);
}
console.log('candidates with differing lowercase:', cands.length);

function runBin(value) {
  const r = spawnSync(BIN, ['--a', value], { encoding: 'buffer', maxBuffer: 1 << 28 });
  return { out: r.stdout, err: r.stderr.toString(), status: r.status };
}

let batches = 0, mismatchBatches = [];
const CHUNK = 400;
for (let i = 0; i < cands.length; i += CHUNK) {
  const group = cands.slice(i, i + CHUNK);
  const value = group.map(cp => String.fromCodePoint(cp)).join('!');
  const expected = group.map(cp => String.fromCodePoint(cp)).join('_').toLowerCase() + '\n';
  const { out, status } = runBin(value);
  batches++;
  if (status !== 0 || Buffer.compare(out, Buffer.from(expected, 'utf8')) !== 0) {
    mismatchBatches.push({ i, group, status });
  }
}
console.log('batches:', batches, 'mismatching batches:', mismatchBatches.length);

// bisect mismatching batches down to individual codepoints
const bad = [];
for (const mb of mismatchBatches) {
  for (const cp of mb.group) {
    const ch = String.fromCodePoint(cp);
    const { out, status } = runBin(ch);
    const expected = Buffer.from(ch.toLowerCase() + '\n', 'utf8');
    if (status !== 0 || Buffer.compare(out, expected) !== 0) {
      bad.push({ cp: 'U+' + cp.toString(16).toUpperCase().padStart(4,'0'),
                 py: out.toString('utf8').replace(/\n$/,''),
                 pyHex: out.toString('hex'),
                 js: ch.toLowerCase(), jsHex: Buffer.from(ch.toLowerCase(),'utf8').toString('hex'),
                 status });
    }
  }
}
console.log('individually divergent codepoints:', bad.length);
console.log(JSON.stringify(bad, null, 1));
EOF
cd /tmp/lead && timeout 900 node case-diff.mjs 2>&1 | tail -40

cat > /tmp/lead/full-sweep.mjs <<'EOF'
import { spawnSync } from 'node:child_process';
const BIN = '/workspace/dataset/test4_executable';
const SEP = new Set([0x09,0x0a,0x0b,0x0c,0x0d,0x20,...Array.from({length:15},(_,i)=>0x21+i),
  ...Array.from({length:7},(_,i)=>0x3a+i),0x5b,0x5d,0x5e,0x5f,0x60,0x7b,0x7c,0x7d,0x7e]);
