const INDENT_INCREMENT = 2;
const MAX_HELP_POSITION = 24;
const MIN_HELP_WIDTH = 11;
const DEFAULT_COLUMNS = 80;

/**
 * Mirrors `shutil.get_terminal_size().columns - 2`, which is how `argparse` sizes
 * itself: an explicit `COLUMNS` environment variable wins, then the real terminal
 * width, then the 80-column fallback used whenever stdout is not a terminal (which is
 * the case whenever output is piped or captured).
 */
export function getFormatterWidth(env = process.env, stdout = process.stdout) {
  const fromEnv = Number.parseInt(env.COLUMNS ?? '', 10);
  if (Number.isInteger(fromEnv) && fromEnv > 0) return fromEnv - 2;
  if (stdout && stdout.isTTY && Number.isInteger(stdout.columns) && stdout.columns > 0) {
    return stdout.columns - 2;
  }
  return DEFAULT_COLUMNS - 2;
}

