const INDENT_INCREMENT = 2;
const MAX_HELP_POSITION = 24;
const MIN_HELP_WIDTH = 11;
const DEFAULT_COLUMNS = 80;

/**
 * Mirrors `shutil.get_terminal_size().columns - 2`, which is how `argparse` sizes
 * itself: an explicit `COLUMNS` environment variable wins, then the real terminal
 * width, then the 80-column fallback used whenever stdout is not a terminal (which is
 * the case whenever output is piped or captured).
 *
 * `int(os.environ['COLUMNS'])` is strict — a non-integer value raises and is ignored
 * rather than being parsed up to the first bad character — and a non-positive value
 * also falls through to querying the terminal.
 */
export function getFormatterWidth(env = process.env, stdout = process.stdout) {
  const raw = env.COLUMNS;
  if (raw !== undefined && /^\s*[+-]?\d+\s*$/.test(raw)) {
    const columns = Number.parseInt(raw, 10);
    if (columns > 0) return columns - 2;
  }
  if (stdout && stdout.isTTY && Number.isInteger(stdout.columns) && stdout.columns > 0) {
    return stdout.columns - 2;
  }
  return DEFAULT_COLUMNS - 2;
}

/**
 * `HelpFormatter.__init__`'s clamp:
 * `min(max_help_position, max(width - 20, indent_increment * 2))`.
 *
 * This is what makes narrow terminals reflow rather than just truncate. At the usual
 * 78-column width it evaluates to 24 and help starts at column 14; at `COLUMNS=20`
 * (width 18) it collapses to 4, which pushes every invocation onto its own line and
 * indents its help by four spaces instead.
 */
function maxHelpPosition(width) {
  return Math.min(MAX_HELP_POSITION, Math.max(width - 20, INDENT_INCREMENT * 2));
}

