/** `HelpFormatter._get_default_metavar_for_optional` — the dest, uppercased. */
const defaultMetavar = (action) => action.dest.toUpperCase();

/** `HelpFormatter._format_args` for `nargs=None`: a single metavar. */
function formatArgs(action) {
  if (action.argCount === 0) return '';
  return action.metavar ?? defaultMetavar(action);
}

/**
 * `HelpFormatter._format_action_invocation`, e.g. `-h, --help` or `--a A`.
 */
export function formatActionInvocation(action) {
  const argsString = formatArgs(action);
  const joined = action.optionStrings.join(', ');
  return argsString ? `${joined} ${argsString}` : joined;
}

/**
 * One usage fragment per action: `[-h]` for optional actions, `--a A` for required
 * ones. Mirrors `HelpFormatter._get_actions_usage_parts`.
 */
export function formatActionsUsageParts(actions) {
  return actions.map((action) => {
    const argsString = formatArgs(action);
    const optionString = action.optionStrings[0];
    const part = argsString ? `${optionString} ${argsString}` : optionString;
    return action.required ? part : `[${part}]`;
  });
}

/**
 * Renders the `usage:` block, including `argparse`'s hanging-indent wrapping for the
 * case where prog plus all the parts do not fit the available width.
 *
 * @returns {string} Usage text with a single trailing newline.
 */
export function formatUsage(prog, actions, width) {
  const prefix = 'usage: ';
  const optionals = actions.filter((a) => a.optionStrings.length > 0);
  const positionals = actions.filter((a) => a.optionStrings.length === 0);
  const optParts = formatActionsUsageParts(optionals);
  const posParts = formatActionsUsageParts(positionals);

  let usage = [prog, [...optParts, ...posParts].join(' ')].filter(Boolean).join(' ');

  const textWidth = width;
  if (prefix.length + usage.length > textWidth) {
    // Pack parts onto continuation lines aligned under the first part.
    const getLines = (parts, indent, linePrefix) => {
      const lines = [];
      let line = [];
      let lineLen = (linePrefix !== undefined ? linePrefix.length : indent.length) - 1;
      for (const part of parts) {
        if (lineLen + 1 + part.length > textWidth && line.length > 0) {
          lines.push(indent + line.join(' '));
          line = [];
          lineLen = indent.length - 1;
        }
        line.push(part);
        lineLen += 1 + part.length;
      }
      if (line.length > 0) lines.push(indent + line.join(' '));
      if (linePrefix !== undefined && lines.length > 0) {
        lines[0] = lines[0].slice(indent.length);
      }
      return lines;
    };

    let lines;
    if (prefix.length + prog.length <= 0.75 * textWidth) {
      // Short prog: the first group of parts rides on the same line as prog, and
      // continuation lines align just past it.
      const indent = spaces(prefix.length + prog.length + 1);
      if (optParts.length > 0) {
        lines = getLines([prog, ...optParts], indent, prefix);
        lines.push(...getLines(posParts, indent));
      } else if (posParts.length > 0) {
        lines = getLines([prog, ...posParts], indent, prefix);
      } else {
        lines = [prog];
      }
    } else {
      // Long prog: it gets a line to itself and the parts are packed underneath,
      // aligned with the end of the `usage: ` prefix.
      const indent = spaces(prefix.length);
      const parts = [...optParts, ...posParts];
      lines = getLines(parts, indent);
      if (lines.length > 1) {
        lines = [...getLines(optParts, indent), ...getLines(posParts, indent)];
      }
      lines = [prog, ...lines];
    }
    usage = lines.join('\n');
  }

  return `${prefix}${usage}\n`;
}

/**
 * Renders the full `--help` text: usage block, a blank line, then each action group.
 *
 * @param {string} prog
 * @param {Array<{title: string, actions: object[]}>} groups
 * @returns {string} Help text with a single trailing newline.
 */
export function formatHelp(prog, actions, groups, width) {
  const shown = actions;
  const actionMaxLength = Math.max(
    0,
    ...shown.map((a) => formatActionInvocation(a).length + INDENT_INCREMENT),
  );
  const helpPosition = Math.min(actionMaxLength + 2, MAX_HELP_POSITION);
  const helpWidth = Math.max(width - helpPosition, MIN_HELP_WIDTH);
  const actionWidth = helpPosition - INDENT_INCREMENT - 2;

  const formatAction = (action) => {
    const invocation = formatActionInvocation(action);
    let header;
    let indentFirst = 0;
    if (!action.help) {
      // No help text: emit the invocation alone, unpadded.
      return `${spaces(INDENT_INCREMENT)}${invocation}\n`;
    }
    if (invocation.length <= actionWidth) {
      header = `${spaces(INDENT_INCREMENT)}${invocation.padEnd(actionWidth)}  `;
    } else {
      header = `${spaces(INDENT_INCREMENT)}${invocation}\n`;
      indentFirst = helpPosition;
    }
    const helpLines = wrapText(action.help, helpWidth);
    let out = header;
    out += `${spaces(indentFirst)}${helpLines[0] ?? ''}\n`;
    for (const line of helpLines.slice(1)) out += `${spaces(helpPosition)}${line}\n`;
    return out;
  };

  let body = '';
  for (const group of groups) {
    const items = group.actions.map(formatAction).join('');
    if (!items) continue; // empty groups (e.g. "positional arguments") vanish entirely
    body += `\n${group.title}:\n${items}\n`;
  }

  // `format_help` collapses runs of 3+ newlines to 2, then normalises the edges.
  const help = `${formatUsage(prog, shown, width)}\n${body}`;
  return `${help.replace(/\n{3,}/g, '\n\n').replace(/^\n+|\n+$/g, '')}\n`;
}

