/**
 * UTF-8 codec with CPython's `surrogateescape` error handler.
 *
 * WHY A HAND-ROLLED CODEC
 * -----------------------
 * `Buffer.toString('utf8')` is lossy: it replaces every malformed byte with U+FFFD, so
 * the original bytes can never be recovered. CPython instead decodes `sys.argv` (and
 * encodes `sys.stdout`) with `surrogateescape`, which smuggles each undecodable byte
 * `b` through as the lone low surrogate U+DC00+b and turns it back into `b` on the way
 * out. The reference binary demonstrably round-trips arbitrary garbage:
 *
 *     --a $'\xff'          -> ff
 *     --a $'\xed\xa0\x80'  -> ed a0 80      (an encoded surrogate; still byte-exact)
 *     --a $'\xe0A'         -> e0 61         (bad byte escaped, then 'A' lowercased)
 *
 * That last case pins down the recovery granularity: decoding resumes immediately
 * after the single offending byte rather than skipping the whole malformed run. The
 * distinction turns out not to be observable — a UTF-8 continuation byte is never a
 * valid start byte, so it would be escaped on the next iteration anyway — but decoding
 * one byte at a time is the model that is directly supported by the evidence.
 *
 * The escaped bytes then pass through the rest of the pipeline untouched: U+DC80..
 * U+DCFF are not separators and have no lowercase mapping.
 */

const SURROGATE_ESCAPE_BASE = 0xdc00;

/** True for the lone low surrogates that `surrogateescape` uses (U+DC80..U+DCFF). */
const isEscapedByte = (unit) => unit >= 0xdc80 && unit <= 0xdcff;

/**
 * Well-formed UTF-8 byte sequences (RFC 3629 §4). Returns the length of the valid
 * sequence starting at `i`, or 0 when the bytes there are malformed. Overlong forms,
 * encoded surrogates (U+D800..U+DFFF) and values above U+10FFFF are all rejected, just
 * as CPython's strict decoder rejects them.
 */
function sequenceLength(bytes, i) {
  const b0 = bytes[i];
  const cont = (k, lo = 0x80, hi = 0xbf) => bytes[i + k] >= lo && bytes[i + k] <= hi;

  if (b0 <= 0x7f) return 1;
  if (b0 >= 0xc2 && b0 <= 0xdf) return cont(1) ? 2 : 0; // 0xC0/0xC1 would be overlong
  if (b0 === 0xe0) return cont(1, 0xa0, 0xbf) && cont(2) ? 3 : 0; // reject overlong
  if (b0 === 0xed) return cont(1, 0x80, 0x9f) && cont(2) ? 3 : 0; // reject surrogates
  if ((b0 >= 0xe1 && b0 <= 0xec) || b0 === 0xee || b0 === 0xef) {
    return cont(1) && cont(2) ? 3 : 0;
  }
  if (b0 === 0xf0) return cont(1, 0x90, 0xbf) && cont(2) && cont(3) ? 4 : 0; // overlong
  if (b0 >= 0xf1 && b0 <= 0xf3) return cont(1) && cont(2) && cont(3) ? 4 : 0;
  if (b0 === 0xf4) return cont(1, 0x80, 0x8f) && cont(2) && cont(3) ? 4 : 0; // > U+10FFFF
  return 0;
}

/**
 * `bytes.decode('utf-8', errors='surrogateescape')`.
 *
 * @param {Uint8Array} bytes
 * @returns {string}
 */
export function decodeSurrogateEscape(bytes) {
  let out = '';
  let i = 0;
  while (i < bytes.length) {
    const length = sequenceLength(bytes, i);
    if (length === 0) {
      out += String.fromCharCode(SURROGATE_ESCAPE_BASE + bytes[i]);
      i += 1;
      continue;
    }
    if (length === 1) {
      out += String.fromCharCode(bytes[i]);
      i += 1;
      continue;
    }
    let cp = bytes[i] & (0xff >> (length + 1));
    for (let k = 1; k < length; k += 1) cp = (cp << 6) | (bytes[i + k] & 0x3f);
    out += String.fromCodePoint(cp);
    i += length;
  }
  return out;
}

/**
 * `text.encode('utf-8', errors='surrogateescape')`.
 *
 * @param {string} text
 * @returns {Buffer}
 */
export function encodeSurrogateEscape(text) {
  const bytes = [];
  for (let i = 0; i < text.length; i += 1) {
    const unit = text.charCodeAt(i);

    if (isEscapedByte(unit)) {
      bytes.push(unit & 0xff);
      continue;
    }

    let cp = unit;
    if (unit >= 0xd800 && unit <= 0xdbff) {
      const low = text.charCodeAt(i + 1);
      if (low >= 0xdc00 && low <= 0xdfff) {
        cp = (unit - 0xd800) * 0x400 + (low - 0xdc00) + 0x10000;
        i += 1;
      } else {
        // CPython raises UnicodeEncodeError for a lone surrogate outside the
        // U+DC80..U+DCFF escape window. Unreachable via this program's inputs:
        // every high surrogate here comes from a genuine astral character.
        throw new RangeError(`surrogates not allowed: U+${unit.toString(16).toUpperCase()}`);
      }
    } else if (unit >= 0xdc00 && unit <= 0xdfff) {
      throw new RangeError(`surrogates not allowed: U+${unit.toString(16).toUpperCase()}`);
    }

    if (cp <= 0x7f) {
      bytes.push(cp);
    } else if (cp <= 0x7ff) {
      bytes.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
    } else if (cp <= 0xffff) {
      bytes.push(0xe0 | (cp >> 12), 0x80 | ((cp >> 6) & 0x3f), 0x80 | (cp & 0x3f));
    } else {
      bytes.push(
        0xf0 | (cp >> 18),
        0x80 | ((cp >> 12) & 0x3f),
        0x80 | ((cp >> 6) & 0x3f),
        0x80 | (cp & 0x3f),
      );
    }
  }
  return Buffer.from(bytes);
}

