/**
 * `sys.argv` equivalent — the command-line arguments as CPython sees them.
 *
 * `process.argv` has already been decoded by Node, which substitutes U+FFFD for any
 * byte sequence that is not valid UTF-8. CPython instead decodes with
 * `surrogateescape`, so a malformed argument survives intact all the way back out to
 * stdout. To reproduce that, the raw bytes are recovered from `/proc/self/cmdline`
 * (NUL-separated, exactly as the kernel stored them at exec time) and decoded here.
 *
 * On any platform or configuration where that file is unavailable, this degrades to
 * Node's own decoding — correct for every well-formed UTF-8 argument, which is all a
 * non-Linux host could reasonably be handed.
 */

import { readFileSync } from 'node:fs';
import { decodeSurrogateEscape } from './utf8_surrogateescape.mjs';

const CMDLINE = '/proc/self/cmdline';

/**
 * Raw argument bytes, excluding the interpreter and the script path.
 *
 * The user's arguments are always the final entries of the command line: Node strips
 * its own execArgv from `process.argv` but never reorders what follows the script, so
 * taking the last `process.argv.length - 2` entries lines the two views up regardless
 * of how many `--flag`s preceded the script name.
 *
 * @returns {?Buffer[]} null when the raw bytes cannot be read.
 */
function rawArgBytes() {
  let raw;
  try {
    raw = readFileSync(CMDLINE);
  } catch {
    return null;
  }

  // Split on NUL and drop the trailing empty piece left by the final terminator.
  const entries = [];
  let start = 0;
  for (let i = 0; i < raw.length; i += 1) {
    if (raw[i] !== 0) continue;
    entries.push(raw.subarray(start, i));
    start = i + 1;
  }
  if (start < raw.length) entries.push(raw.subarray(start));

  const wanted = process.argv.length - 2;
  if (wanted < 0 || entries.length < wanted) return null;
  return entries.slice(entries.length - wanted);
}

/**
 * The arguments after the script name, decoded the way CPython decodes `sys.argv`.
 *
 * @returns {string[]}
 */
export function getArgv() {
  const raw = rawArgBytes();
  if (raw === null) return process.argv.slice(2);
  return raw.map(decodeSurrogateEscape);
}

