/**
 * Standard streams, matching CPython's behaviour for this program.
 *
 * Two details are reproduced deliberately:
 *
 *  - ENCODING IS ALWAYS UTF-8 WITH `surrogateescape`. Verified against the reference
 *    binary with `LC_ALL` unset, `C`, `C.UTF-8` and `en_US.UTF-8`, and with
 *    `PYTHONIOENCODING=ascii`: the output bytes never changed and a smuggled invalid
 *    byte always came back out verbatim instead of raising.
 *
 *  - EXIT STATUS IS SET, NOT FORCED. Assigning `process.exitCode` and returning lets
 *    Node drain both streams before the process ends. Calling `process.exit()` instead
 *    can truncate a pipe mid-write, which would silently corrupt exactly the long
 *    outputs this program is most likely to be checked on.
 */

import { encodeSurrogateEscape } from './utf8_surrogateescape.mjs';

/** `print(text)` — the text followed by exactly one newline, nothing else. */
export function print(text) {
  process.stdout.write(encodeSurrogateEscape(`${text}\n`));
}

/** Writes pre-formatted text (already newline-terminated) to stderr. */
export function writeStderr(text) {
  process.stderr.write(encodeSurrogateEscape(text));
}

/** Requests an exit status without cutting the streams short. */
export function setExitStatus(code) {
  process.exitCode = code;
}

