#!/usr/bin/env node
/**
 * Node.js port of:
 *
 *     import argparse
 *     from boltons.strutils import slugify
 *
 *     parser = argparse.ArgumentParser()
 *     parser.add_argument('--a', type=str, required=True)
 *     args = parser.parse_args()
 *
 *     result = slugify(args.a)
 *     print(result)
 *
 * Run it the same way as the reference binary:
 *
 *     node test4.mjs --a "First post! Hi!!!!~1  "   ->  first_post_hi_1
 */

import { ParserExit } from './lib/argparse/errors.mjs';
import { ArgumentParser } from './lib/argparse/parser.mjs';
import { slugify } from './lib/boltons/strutils.mjs';
import { getArgv } from './lib/py/argv.mjs';
import { print, setExitStatus, writeStderr } from './lib/py/stdio.mjs';

/** `os.path.basename(sys.argv[0])`, which is what argparse uses as the program name. */
function programName() {
  const script = process.argv[1] ?? '';
  const slash = script.lastIndexOf('/');
  return slash === -1 ? script : script.slice(slash + 1);
}

function main() {
  const parser = new ArgumentParser({ prog: programName() });
