// Compares the help/usage RENDERING algorithm directly, using the same prog name as
// the reference binary so that differences in name length can't confound the result.
import { spawnSync } from 'node:child_process';
import { ArgumentParser } from '/output/lib/argparse/parser.mjs';

const BIN = '/workspace/dataset/test4_executable';

function build(width) {
  const parser = new ArgumentParser({ prog: 'test4_executable', width });
  parser.addArgument('--a', { type: String, required: true });
  return parser;
}

let fails = 0;
let total = 0;
for (let columns = 4; columns <= 140; columns += 1) {
  const env = { ...process.env, COLUMNS: String(columns) };
  const width = columns - 2;

  const pyHelp = spawnSync(BIN, ['--help'], { encoding: 'utf8', env }).stdout;
  const jsHelp = build(width).formatHelp();
  total += 1;
  if (pyHelp !== jsHelp) {
    fails += 1;
    console.log(`--- HELP mismatch COLUMNS=${columns}\nPY:\n${pyHelp}JS:\n${jsHelp}`);
  }

  const pyErr = spawnSync(BIN, [], { encoding: 'utf8', env }).stderr;
  const jsErr = `${build(width).formatUsage()}test4_executable: error: the following arguments are required: --a\n`;
  total += 1;
  if (pyErr !== jsErr) {
    fails += 1;
    console.log(`--- USAGE mismatch COLUMNS=${columns}\nPY:\n${pyErr}JS:\n${jsErr}`);
  }
}
console.log(`formatter: ${total - fails}/${total} matched across COLUMNS 4..140`);

